 search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6', arrow:'M7 5l7 7-7 7', external:'M14 3h7v7 M21 3 10 14 M10 4H4v16h16v-6',
