 cloud:'M7 18h11a4 4 0 0 0 0-8 6 6 0 0 0-12-1 4.5 4.5 0 0 0 1 9', rain:'M6 16h12a4 4 0 0 0 0-8 6 6 0 0 0-11-1 4 4 0 0 0-1 9 M8 19l-1 3 M15 19l-1 3',
